import{_ as r,l,o as t,c as n,v as e,p as s,x as i,d as E,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"引用与归因","description":"","frontmatter":{"title":"引用与归因","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/citation-attribution.md","filePath":"llm/citation-attribution.md","lastUpdated":1789023840000}'),p={name:"llm/citation-attribution.md"};function h(c,a,_,m,u,f){const o=l("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="引用与归因" tabindex="-1">引用与归因 <a class="header-anchor" href="#引用与归因" aria-label="Permalink to &quot;引用与归因&quot;">​</a></h1><div class="epigraph"><p>检索到了不等于回答忠于检索。引用必须能解析到块，并且命题能被该块支撑，否则只是学术文风。</p><footer>—— Gao 等 ALCE；主干 [诚实与引用](/llm/honesty-citations)</footer></div><p><a href="/llm/multi-hop-retrieval">上一课</a>让证据链变长，张冠李戴的机会变多。主干诚实课已区分虚构引用；本课把 RAG 场景的归因钉进评测进阶的检索单元。缺口是：<strong>出处可点击且支撑命题</strong>，不是脚标长得像论文。后课 RAGAS 会把忠实度收成自动指标，本课先定义要测什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三种失败：无引用；引用了未检索的编号；检索了块但命题来自参数记忆或另一块。Gao 等人的 ALCE 把自动引用评测做成可复核：引用是否指向真实文档、句子是否被引用支撑。与幻觉分类课的「归因幻觉」是同一对象在 RAG 管道里的名字。</p><p>强制「每句都要有标」会诱发随机贴标。应要求：需核验的命题有标，寒暄无标；评测分列覆盖率与精确率。</p><p><span class="marginnote">块太大，一条引用等于「整页都算」；块太小，一条命题要跨多个标。切分课的粒度就是归因粒度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成时只允许引用检索集合内的 ID。事后：解析标号；对每个带标命题做支撑判断（NLI 或人）。报告：可解析率、支撑精确率、无支撑率。多跳要按跳对齐：桥接命题应引用第一跳块。禁止用未校准法官只打「看起来有出处」。</p>',9)),(t(),s(A,null,{default:i(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RET%5B%22%E6%A3%80%E7%B4%A2%E9%9B%86%E5%90%88%22%5D%20--%3E%20GEN%5B%22%E5%B8%A6%20ID%20%E7%9A%84%E7%94%9F%E6%88%90%22%5D%0A%20%20GEN%20--%3E%20PAR%5B%22%E8%A7%A3%E6%9E%90%E5%BC%95%E7%94%A8%22%5D%0A%20%20PAR%20--%3E%20SUP%5B%22%E5%91%BD%E9%A2%98%E6%98%AF%E5%90%A6%E8%A2%AB%E5%9D%97%E6%94%AF%E6%92%91%22%5D%0A%20%20SUP%20--%3E%20MET%5B%22%E5%8F%AF%E8%A7%A3%E6%9E%90%E7%8E%87%20%2F%20%E6%94%AF%E6%92%91%E7%B2%BE%E7%A1%AE%E7%8E%87%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>语言模型有「像论文」的先验，会补全括号与作者年。RAG 若不把 ID 当作闭集约束（受限解码或后处理过滤），先验会压过检索集合。支撑失败来自参数与上下文混合：窗口里有块，模型仍用记忆填细节。忠实性训练与约束解码改的是这条混合，不是再加一个更强的检索器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做法学意义上的出处保证。下一课 RAG 评测把归因、相关性、上下文利用收成套件（RAGAS 一类）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归因 = 可解析 ID + 块支撑命题；分列覆盖与精确。</li><li>引用闭集约束，防止虚构脚标。</li><li>切分粒度决定引用粒度。</li><li>出处：Gao 等 ALCE；诚实与引用课；幻觉分类课。</li></ul>',6))])}const B=r(p,[["render",h]]);export{T as __pageData,B as default};
